<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUse;

/**
 * @template-extends ArrayIterator<int, TenantTermsOfUse>
 */
class TenantTermsOfUseSlide extends \ArrayIterator
{
    private readonly ?TenantTermsOfUse $last;
    private readonly TenantTermsOfUseCursor $nextCursor;
    public function __construct(
        private readonly ?\Closure $next,
        private readonly ?TenantTermsOfUseCursor $cursor,
        private readonly array $values
    ) {
        parent::__construct($values);
        $this->last = $values ? end($values) : null;
        $cursor = $this->cursor ?? new TenantTermsOfUseCursor(limit: 1000);
        $this->nextCursor = null === $this->last ? $cursor : $cursor->next($this->last, null);
    }
    public function cursor(): ?TenantTermsOfUseCursor
    {
        return $this->cursor;
    }
    public function nextCursor(): TenantTermsOfUseCursor
    {
        return $this->nextCursor;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?TenantTermsOfUse
    {
        return parent::current();
    }
    public function map(\Closure $fn): TenantTermsOfUseSlide
    {
        return new TenantTermsOfUseSlide($this->next, $this->cursor, array_map($fn, $this->values));
    }
    public function slide(\Closure $fn): TenantTermsOfUseSlide
    {
        $collected = array_values(array_filter($this->values, $fn));
        $cursor = $this->cursor;
        if (null !== $cursor && null !== $this->next) {
            $limit = $cursor->limit();
            $current = $this;
            while (count($collected) < $limit && count($current->values) >= $limit) {
                $current = ($this->next)($current, $current->nextCursor);
                $collected = array_merge($collected, array_values(array_filter($current->values, $fn)));
            }
            $collected = array_slice($collected, 0, $limit);
        }
        return new TenantTermsOfUseSlide($this->next, $cursor, $collected);
    }
}
